import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;
import java.util.logging.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String templateName = req.getParameter("template");
        String reportId = req.getParameter("report_id");
        String format = req.getParameter("format");

        if (templateName == null || reportId == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(csv|json|xml)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try {
            // Load template from database
            String templateQuery = loadTemplate(templateName);
            if (templateQuery == null) {
                resp.sendError(404, "Template not found");
                return;
            }

            // Substitute report parameters into the template query
            Map<String, String> params = new HashMap<>();
            params.put("report_id", reportId);
            params.put("format", format != null ? format : "json");
            params.put("requester", req.getRemoteUser() != null ? req.getRemoteUser() : "anonymous");

            // StringSubstitutor uses ${...} syntax - template contains placeholders
            StringSubstitutor sub = new StringSubstitutor(params);
            String finalQuery = sub.replace(templateQuery);

            log.info("Executing report query for template: " + templateName);

            // Execute the constructed query
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(finalQuery)) {

                resp.setContentType("application/" + (format != null ? format : "json"));
                PrintWriter out = resp.getWriter();

                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();

                out.println("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.print("{");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.print("\"" + meta.getColumnName(i) + "\":");
                        out.print("\"" + rs.getString(i) + "\"");
                    }
                    out.print("}");
                    first = false;
                }
                out.println("]");
            }
        } catch (SQLException e) {
            log.severe("SQL error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String loadTemplate(String name) throws SQLException {
        // Templates are stored in a config table, editable by admins
        String sql = "SELECT query_text FROM report_templates WHERE name = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, name);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getString("query_text");
                }
            }
        }
        return null;
    }

    // Audit logging for compliance
    private void auditLog(String user, String action, String detail) {
        log.info(String.format("AUDIT: user=%s action=%s detail=%s", user, action, detail));
    }
}
